data.source:
zal layers 1;
abstraction reservation_meaning;
idea intent: "An accepted request identity must not acquire the resource twice.";
assume lifetime: "One modeled process lifetime. No persistent identity or external delivery claim.";
assume authorization: "The supplied authorized Boolean is an observation, not authenticated truth.";
question identity_reuse: "After release, should the same identity be accepted again, rejected, or is neither interpretation right?";
model detailed begin
zal 1;
machine audited_one_use;
states fresh_a, fresh_b, held_a, held_b, spent_a, spent_b;
events release, reserve;
context authorized;
initial fresh_a;
step atomic; frame control_only;
default reject unmatched unchanged;
rule r00: fresh_a + release [!authorized] -> reject unauthorized unchanged;
rule r01: fresh_a + release [authorized] -> reject not_held unchanged;
rule r02: fresh_a + reserve [!authorized] -> reject unauthorized unchanged;
rule r03: fresh_a + reserve [authorized] -> accept held_b;
rule r04: fresh_b + release [!authorized] -> reject unauthorized unchanged;
rule r05: fresh_b + release [authorized] -> reject not_held unchanged;
rule r06: fresh_b + reserve [!authorized] -> reject unauthorized unchanged;
rule r07: fresh_b + reserve [authorized] -> accept held_a;
rule r08: held_a + release [!authorized] -> reject unauthorized unchanged;
rule r09: held_a + release [authorized] -> accept spent_b;
rule r10: held_a + reserve [!authorized] -> reject unauthorized unchanged;
rule r11: held_a + reserve [authorized] -> reject duplicate unchanged;
rule r12: held_b + release [!authorized] -> reject unauthorized unchanged;
rule r13: held_b + release [authorized] -> accept spent_a;
rule r14: held_b + reserve [!authorized] -> reject unauthorized unchanged;
rule r15: held_b + reserve [authorized] -> reject duplicate unchanged;
rule r16: spent_a + release [!authorized] -> reject unauthorized unchanged;
rule r17: spent_a + release [authorized] -> reject not_held unchanged;
rule r18: spent_a + reserve [!authorized] -> reject unauthorized unchanged;
rule r19: spent_a + reserve [authorized] -> reject duplicate unchanged;
rule r20: spent_b + release [!authorized] -> reject unauthorized unchanged;
rule r21: spent_b + release [authorized] -> reject not_held unchanged;
rule r22: spent_b + reserve [!authorized] -> reject unauthorized unchanged;
rule r23: spent_b + reserve [authorized] -> reject duplicate unchanged;
end model;
model lifecycle begin
zal 1;
machine one_use;
states held, released, unseen;
events release, reserve;
context authorized;
initial unseen;
step atomic; frame control_only;
default reject unmatched unchanged;
rule r00: held + release [!authorized] -> reject unauthorized unchanged;
rule r01: held + release [authorized] -> accept released;
rule r02: held + reserve [!authorized] -> reject unauthorized unchanged;
rule r03: held + reserve [authorized] -> reject duplicate unchanged;
rule r04: released + release [!authorized] -> reject unauthorized unchanged;
rule r05: released + release [authorized] -> reject not_held unchanged;
rule r06: released + reserve [!authorized] -> reject unauthorized unchanged;
rule r07: released + reserve [authorized] -> reject duplicate unchanged;
rule r08: unseen + release [!authorized] -> reject unauthorized unchanged;
rule r09: unseen + release [authorized] -> reject not_held unchanged;
rule r10: unseen + reserve [!authorized] -> reject unauthorized unchanged;
rule r11: unseen + reserve [authorized] -> accept held;
end model;
model alternative begin
zal 1;
machine reusable;
states held, released, unseen;
events release, reserve;
context authorized;
initial unseen;
step atomic; frame control_only;
default reject unmatched unchanged;
rule r00: held + release [!authorized] -> reject unauthorized unchanged;
rule r01: held + release [authorized] -> accept released;
rule r02: held + reserve [!authorized] -> reject unauthorized unchanged;
rule r03: held + reserve [authorized] -> reject duplicate unchanged;
rule r04: released + release [!authorized] -> reject unauthorized unchanged;
rule r05: released + release [authorized] -> reject not_held unchanged;
rule r06: released + reserve [!authorized] -> reject unauthorized unchanged;
rule r07: released + reserve [authorized] -> accept held;
rule r08: unseen + release [!authorized] -> reject unauthorized unchanged;
rule r09: unseen + release [authorized] -> reject not_held unchanged;
rule r10: unseen + reserve [!authorized] -> reject unauthorized unchanged;
rule r11: unseen + reserve [authorized] -> accept held;
end model;
derive occupancy from lifecycle observe class using {"held":"busy","released":"idle","unseen":"idle"};
derive eligibility from lifecycle observe class using {"held":"used","released":"used","unseen":"eligible"};
derive activity from occupancy observe class using {"busy":"system","idle":"system"};
link audit_erasure from detailed to lifecycle as exact using {"fresh_a":"unseen","fresh_b":"unseen","held_a":"held","held_b":"held","spent_a":"released","spent_b":"released"};
link hide_identity from lifecycle to occupancy as sound using {"held":"busy","released":"idle","unseen":"idle"};
link expose_eligibility from lifecycle to eligibility as sound using {"held":"used","released":"used","unseen":"eligible"};
link hide_occupancy from occupancy to activity as sound using {"busy":"system","idle":"system"};
link eligibility_summary from eligibility to activity as sound using {"eligible":"system","used":"system"};

